/**
 * One row of a share chart (G4b): [name] and [valueText] as text („Gesundheit“ „42“), [value] the length of the fill
 * on the scale; [current] = the current period (chartBarCurrent). [expected] (D105 (34), spec/02 §3.7): the expected count on
 * the same scale, drawn as a thin textMuted line across the bar, [expectedText] its value as TalkBack reads it.
 */
@Immutable
data class SbShareRow(
    val name: String,
    val value: Float,
    val valueText: String,
    val current: Boolean = false,
    val expected: Float? = null,
    val expectedText: String? = null,
)

/**
 * Shares as labelled rows (G4b, spec/02 §3.7 `sb-chart__rows`): per row the name in caption with its value at the
 * label weight and tabular figures, in a column of 128 dp × text scale (the web's 8rem), then a 12 dp bar: the fill
 * (chartBar, chartBarCurrent for the current period) on the track (surfaceSunken, the whole) when [track]. [total] is
 * the whole (100 for percent, else the sum of the parts; without a track it may be the largest row). Parts keep one
 * order over time. Also the rating distribution (spec/02 §3.20: names „5 von 5:“ … „1 von 5:“, read „5 von 5: 20“).
 * One TalkBack node per row. Counts against an expected value (D105 (34), spec/02 §3.7): a row with [SbShareRow.expected]
 * gets a 2 dp textMuted line at that value, 4 dp past the bar above and below, with a 1 dp bg joint on both sides
 * inside the bar (the joint D106 (13)), and „erwartet“ stands once in a legend under the rows; TalkBack reads
 * „<name> <value>, erwartet <expectedText>“. Rows without it draw as before.
 */
@Composable
fun SbShareRows(
    rows: List<SbShareRow>,
    caption: String,
    modifier: Modifier = Modifier,
    total: Float = 100f,
    track: Boolean = true,
) {
    require(rows.isNotEmpty()) { "SbShareRows: no rows" }
    require(total > 0f) { "SbShareRows: the whole must be above 0" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val nameWidth = t.space.s16 * 2 * sbTextScale()
    val m = sbMessages()
    val marked = rows.any { it.expected != null }
    SbChartFigure(caption, modifier) {
        Column(Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(t.space.s2)) {
            rows.forEach { r ->
                val spoken = if (r.expected != null) "${r.name} ${r.valueText}, ${m.chartExpected} ${r.expectedText ?: ""}".trimEnd() else null
                Row(
                    Modifier
                        .fillMaxWidth()
                        .then(
                            if (spoken != null) Modifier.clearAndSetSemantics { contentDescription = spoken }
                            else Modifier.semantics(mergeDescendants = true) { },
                        ),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(t.space.s3),
                ) {
                    val name = buildAnnotatedString {
                        append(r.name)
                        append(" ")
                        withStyle(SpanStyle(fontWeight = ty.label.fontWeight, fontFeatureSettings = ty.numeric.fontFeatureSettings)) {
                            append(r.valueText)
                        }
                    }
                    Text(name, style = ty.caption, color = c.text, modifier = Modifier.width(nameWidth))
                    Canvas(
                        Modifier
                            .weight(1f)
                            .height(if (marked) t.space.s5 else t.space.s3),
                    ) {
                        val bar = t.space.s3.toPx()
                        val top = (size.height - bar) / 2f
                        val rtl = layoutDirection == LayoutDirection.Rtl
                        if (track) drawRect(c.surfaceSunken, Offset(0f, top), Size(size.width, bar))
                        val w = size.width * (r.value / total).coerceIn(0f, 1f)
                        val x = if (rtl) size.width - w else 0f
                        drawRect(if (r.current) t.x.chartBarCurrent else t.x.chartBar, Offset(x, top), Size(w, bar))
                        r.expected?.let { e ->
                            val line = 2.dp.toPx()
                            val joint = 1.dp.toPx()
                            val at = (size.width * (e / total).coerceIn(0f, 1f)).coerceIn(line / 2f + joint, size.width - line / 2f - joint)
                            val cx = if (rtl) size.width - at else at
                            drawRect(c.bg, Offset(cx - line / 2f - joint, top), Size(line + 2f * joint, bar))
                            drawRect(c.textMuted, Offset(cx - line / 2f, 0f), Size(line, size.height))
                        }
                    }
                }
            }
            if (marked) {
                // the word once, beside a sample of the line; each row already says it to TalkBack
                Row(
                    Modifier
                        .padding(top = t.space.s1)
                        .clearAndSetSemantics { },
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(t.space.s2),
                ) {
                    Canvas(Modifier.width(2.dp).height(t.space.s5)) { drawRect(c.textMuted) }
                    Text(m.chartExpected, style = ty.caption, color = c.textMuted)
                }
            }
        }
    }
}
